const fs=require('fs'),path=require('path'),{chromium}=require('playwright');const a=process.argv.slice(2),arg=(n,f='')=>{const i=a.indexOf(n);return i>=0&&a[i+1]?a[i+1]:f};const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),usuario=arg('--usuario','admin'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-botoes-requisitos-legais-20260924.json')),ev=path.resolve('tests/evidencias-botoes-requisitos-legais-20260924');const result={startedAt:new Date().toISOString(),checks:[],status:'REPROVADO',screenshots:[]};const check=(n,o,d='')=>{result.checks.push({name:n,ok:!!o,details:d});console.log(`${o?'PASS':'FAIL'} - ${n}${d?`: ${d}`:''}`);if(!o)throw new Error(n)};async function main(){let b;try{fs.mkdirSync(ev,{recursive:true});b=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const c=cdp?(b.contexts()[0]||await b.newContext()):await b.newContext({viewport:{width:1440,height:900}});const p=cdp?(c.pages()[0]||await c.newPage()):await c.newPage({viewport:{width:1440,height:900}});p.setDefaultTimeout(20000);await p.goto(base+'/index.php',{waitUntil:'domcontentloaded'});await p.locator('#empresa').selectOption({label:empresa}).catch(()=>p.locator('#empresa').selectOption({value:empresa}));await p.locator('#userid').fill(usuario);await p.locator('#senha').fill(senha);await p.locator('form.login-form button[type="submit"]').click();await p.waitForURL(/\/principal\/main\.php/);await p.locator('[data-sidebar-toggle]').click().catch(()=>{});await p.locator('#menuSearch').fill('Requisitos legais');await p.locator('button[data-open-tab][data-tab-url*="modulolegal_requisitoslegais.php"]').click();const f=p.frameLocator('iframe[src*="modulolegal_requisitoslegais.php"]');await f.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});const row=f.locator('#requisitosLegaisBatchGrid tbody tr').first();await row.click();await p.screenshot({path:path.join(ev,'01-grade.png'),fullPage:true});result.screenshots.push(path.join(ev,'01-grade.png'));
const popupTests=[['treinamentos','manutencaolegalrequisitoslegais_treinamentos.php'],['infraestrutura','manutencaolegalrequisitoslegais_infraestrutura.php'],['homologacao','manutencaolegalrequisitoslegais_homologacao.php']];for(const [key,route] of popupTests){const button=f.locator(`[data-open-requisito-popup="${key}"]`);check(`Botão ${key} habilitado`,await button.isEnabled());await button.click();const modal=p.locator('#greenPortalTransacaoModal');await modal.waitFor({state:'visible'});const iframe=modal.locator('iframe');const src=await iframe.getAttribute('src');check(`Popup ${key} abriu no contexto`,src.includes(route)&&src.includes('CODLEGISLACAO=')&&src.includes('CODUNIDADE='),src);await iframe.contentFrame().locator('body').waitFor({state:'visible'});await p.screenshot({path:path.join(ev,`02-${key}.png`),fullPage:true});result.screenshots.push(path.join(ev,`02-${key}.png`));await modal.locator('.btn-close').click();await modal.waitFor({state:'hidden'})}
const padrao=f.locator('[data-open-padrao]').first();check('Botão Padrão presente',await padrao.count()===1);if(await padrao.count()){await padrao.click();const modal=f.locator('#requisitosPadraoModal');await modal.waitFor({state:'visible'});check('Modal Padrão abriu com conteúdo',await modal.locator('[data-requisitos-padrao-texto]').inputValue().then(v=>v.trim().length>0));await modal.locator('.btn-close').click()}
const pdf=f.locator('[data-open-legislacao-pdf]').first();check('Botão PDF presente',await pdf.count()===1);await pdf.click({force:true});const pdfModal=f.locator('#greenPortalPdfModal');await pdfModal.waitFor({state:'visible'});const pdfLink=await pdfModal.locator('[data-pdf-download]').getAttribute('href');check('Modal visual PDF abriu',await pdfModal.isVisible(),pdfLink||'');const pdfResponse=await p.request.get(pdfLink.startsWith('/')?base+pdfLink:pdfLink);const bytes=await pdfResponse.body();check('Download do PDF HTTP 200 e válido',pdfResponse.status()===200&&bytes.subarray(0,5).toString()==='%PDF-',`${pdfResponse.status()} ${bytes.length} bytes`);await p.screenshot({path:path.join(ev,'03-pdf.png'),fullPage:true});result.screenshots.push(path.join(ev,'03-pdf.png'));await pdfModal.locator('.btn-close').click();
const help=f.locator('[data-open-transacao-ajuda]');check('Botão Ajuda presente',await help.count()===1);await help.click();const helpModal=p.locator('[data-popup-transacao-independent].show').last();await helpModal.waitFor({state:'visible'});const helpSrc=await helpModal.locator('iframe').getAttribute('src');check('Ajuda abriu com transação correta',helpSrc.includes('setup_ajuda.php?transacao=modulolegal_requisitoslegais'),helpSrc);await p.screenshot({path:path.join(ev,'04-ajuda.png'),fullPage:true});result.screenshots.push(path.join(ev,'04-ajuda.png'));await helpModal.locator('.btn-close').click();
const mainSrc=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').getAttribute('src');const before=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').count();await f.locator('[data-reload-grid]').click();await f.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});await p.waitForTimeout(500);const after=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').count();const currentSrc=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').getAttribute('src');check('Recarregar manteve contexto da transação',before===after&&currentSrc===mainSrc,`iframes ${before}->${after}`);check('Recarregar manteve a grade carregada',await f.locator('#requisitosLegaisBatchGrid tbody tr').count()>0);result.status='APROVADO'}catch(e){result.error=e.message;throw e}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(b&&!cdp)await b.close()}}main().catch(e=>{console.error(`ERRO FATAL: ${e.stack||e.message}`);process.exit(1)});
